import sys
import heapq

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T_str = next(iterator)
        T = int(T_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            K = int(next(iterator))

            A = []
            for _ in range(N):
                A.append(int(next(iterator)))

            B = []
            for _ in range(N):
                B.append(int(next(iterator)))
        except StopIteration:
            break

        current_interaction = 0
        for i in range(N):
            current_interaction += A[i] * B[i]

        pq = []
        for i in range(N):
            gain = abs(B[i])
            if gain > 0:
                heapq.heappush(pq, (-gain, i))

        remaining_k = K

        while remaining_k > 0 and pq:
            neg_gain, idx = heapq.heappop(pq)
            gain = -neg_gain

            if gain == 0:
                break

            needed = 0
            if B[idx] > 0:
                needed = -A[idx]
            else:
                needed = A[idx]

            if needed <= 0:
                add = remaining_k
                remaining_k = 0
            else:
                add = min(remaining_k, needed)
                remaining_k -= add

            current_interaction += add * gain

            if remaining_k > 0 and needed > 0:
                heapq.heappush(pq, (-gain * 2, idx))

        results.append(str(current_interaction))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
